INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2001,'小米15 5G手机 骁龙8至尊版 徕卡光学镜头 12GB+256GB 白色',449900,260,'/images/ai/zg_phone_blue.jpg',1,1,'12GB+256GB / 骁龙8至尊版 / 6.36英寸小直屏',98000,1,'小屏党等了很久的单手旗舰，6.36英寸直屏握着手不酸，骁龙8至尊版打原神满帧不烫手；预算四千多想要旗舰体验的学生党首选。','2026-09-26 23:13:04','2026-09-27 00:18:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2002,'小米15 Pro 5G手机 骁龙8至尊版 徕卡潜望长焦 16GB+512GB 岩石灰',529900,150,'/images/ai/zg_phone_black.jpg',1,1,'16GB+512GB / 骁龙8至尊版 / 5倍潜望长焦',39000,1,'想要长焦拍演唱会、拍娃拍远处的选它，5倍潜望不糊；2K微曲屏加5400mAh大电池，一天重度使用不用带充电宝。','2026-09-26 23:13:04','2026-09-27 00:18:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2003,'小米15 Ultra 徕卡四摄影像旗舰 16GB+1TB 黑色',699900,60,'/images/ai/zg_phone_silver.jpg',1,1,'16GB+1TB / 一英寸主摄 / 4.7倍潜望长焦',1860,1,'一英寸大底主摄，夜景和逆光直接出片不用修；送摄影爱好者或者自己当主力机都够顶，1TB存视频不慌。','2026-09-26 23:13:04','2026-09-27 00:15:31');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2004,'Redmi K80 5G手机 骁龙8Gen3 2K屏 12GB+256GB 玄夜黑',249900,480,'/images/ai/zg_phone_blue.jpg',1,15,'12GB+256GB / 骁龙8Gen3 / 6.67英寸2K屏',49000,1,'两千五价位能买到骁龙8Gen3加2K屏，性价比摆在这；6550mAh电池两天一充，宿舍党打游戏预算有限就它。','2026-09-26 23:13:04','2026-09-27 00:18:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2005,'Redmi K80 Pro 骁龙8至尊版 120W快充 12GB+256GB 雪岩白',329900,320,'/images/ai/zg_phone_black.jpg',1,15,'12GB+256GB / 骁龙8至尊版 / 120W秒充',9800,1,'K80的加强版，处理器换成骁龙8至尊版，充电120W二十分钟满血；打重度手游又想省钱的学生党看这台。','2026-09-26 23:13:04','2026-09-27 00:15:31');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2006,'Redmi Note 14 Pro 天玑7300 1.5K曲面屏 12GB+256GB 镜瓷白',149900,900,'/images/ai/zg_phone_silver.jpg',1,15,'12GB+256GB / 天玑7300 / 1.5K曲面屏',58000,1,'一千五的价位给了曲面屏和大电池，日常刷视频微信完全够；给爸妈买或者当备用机都合适，摔了也不心疼。','2026-09-26 23:13:04','2026-09-27 00:18:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2007,'Redmi Turbo 4 天玑8400 16GB+512GB 性能小金刚 浅绿色',199900,620,'/images/ai/zg_phone_blue.jpg',1,15,'16GB+512GB / 天玑8400 / 7410mAh电池',35000,1,'七千四毫安大电池是真的能扛，出差一天不用找插座；天玑8400性能够用，两千以内要大内存大电池的选它。','2026-09-26 23:13:04','2026-09-27 00:18:41');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2008,'华为Mate 70 麒麟9020 鸿蒙NEXT 12GB+512GB 云杉绿',549900,180,'/images/ai/zg_phone_silver.jpg',1,3,'12GB+512GB / 麒麟9020 / 鸿蒙NEXT',112000,1,'鸿蒙生态和多设备协同是它的强项，家里有华为平板手表的联动很顺；卫星消息功能户外应急能用上，商务人士送长辈都体面。','2026-09-26 23:13:04','2026-09-27 00:19:13');
