INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2135,'格力落地扇家用静音电风扇 大风力立式摇头宿舍办公室',29900,300,'/images/ai/zg_fan.jpg',3,48,'16英寸 / 三档风速 / 广角摇头 / 可拆洗扇叶',6700,1,'三百块的落地扇，风力足噪音小，客厅卧室搬着走。扇叶能拆下来水洗，用两年不积灰。租房过渡或者空调房里加个循环风的选它。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2136,'戴森HD16 电吹风机家用负离子护发 大风力速干礼盒装',299900,80,'/images/ai/zg_hairdryer.jpg',3,56,'智能温控 / 负离子 / 多风嘴 / 礼盒装',1600,1,'吹得快还不烫头发，长发十分钟就干，比老式吹风机省一半时间。温控不会越吹越毛躁。送礼首选，送女朋友送妈妈这个价位的吹风机很有分量。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2137,'松下剃须刀电动刮胡刀男士 往复式三刀头全身水洗充电式',89900,180,'/images/ai/zg_shaver.jpg',3,61,'三刀头往复式 / 全身水洗 / 磁悬浮马达 / 60分钟续航',2400,1,'往复式刮得干净，硬胡子也一遍过不留茬。整个机身能冲水洗，用完直接水龙头下冲。送男生送爸爸选它，九百这个档位很体面。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2138,'飞利浦S5000系列剃须刀 旋转式三刀头 男士电动刮胡刀快充',59900,240,'/images/ai/zg_shaver.jpg',3,60,'三刀头旋转式 / 5向贴面 / 干湿两用 / 1小时快充',4100,1,'旋转式的刀头贴脸更服帖，下巴脖子这些拐角刮得干净。干湿两用可以配泡沫刮，敏感肌不容易红。六百预算买飞利浦主力款不会错。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2139,'素士电动牙刷声波震动 成人款智能计时情侣套装学生党',19900,620,'/images/ai/zg_toothbrush.jpg',3,63,'声波震动 / 4种模式 / 2分钟计时 / Type-C充电',9800,1,'两百块的声波牙刷，震感和千元款差别不大。两分钟自动提醒换区域，刷牙不再随便糊弄。学生党入门电动牙刷、买情侣款送人的都选它。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2140,'飞利浦电动牙刷HX6系列 成人充电式声波震动护龈送礼盒',39900,280,'/images/ai/zg_toothbrush.jpg',3,60,'声波震动 / 3种模式 / 14天续航 / 含旅行盒',5200,1,'充一次能用两周，出差不用带充电线。护龈模式对刷牙出血的人友好。四百档买大牌声波牙刷，送人自用都稳妥。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2141,'飞科电吹风机家用大功率负离子护发 学生党宿舍速干吹风筒',9900,1100,'/images/ai/zg_hairdryer.jpg',3,62,'1800W / 负离子 / 三档温控 / 折叠便携',22000,1,'一百块以内的吹风机里最稳的，风大干得快。可折叠塞行李箱，出差旅行带着方便。学生党宿舍用、或者租房过渡买一台完全不心疼。','2026-09-26 23:27:14','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2142,'优衣库男装 轻型羽绒外套 便携收纳防风保暖 秋冬通勤夹克',59900,260,'/images/ai/zg_down_jacket.jpg',4,9,'S-3XL / 白鸭绒750蓬松度 / 可收纳袋 / 多色',3400,1,'轻到可以塞进自带的小收纳袋，通勤包里常备一件应对降温。比厚羽绒服利落，西装外面套也不显臃肿。上班族和学生党秋冬过渡都合适。','2026-09-26 23:30:33','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2143,'优衣库 HEATTECH 保暖内衣套装 男女款发热打底 秋冬修身',19900,520,'/images/ai/zg_tshirt.jpg',4,9,'S-3XL / 吸湿发热 / 圆领+长裤套装 / 多色',20000,1,'薄薄一层贴身穿不臃肿，毛衣里面套一件整个冬天都够。吸湿发热面料不会闷汗。两百块内买套保暖内衣，送爸妈送对象都实用。','2026-09-26 23:30:33','2026-09-27 00:18:41');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2144,'优衣库男装 弹力修身牛仔裤 直筒休闲长裤 2026春季新款',29900,380,'/images/ai/zg_pants.jpg',4,9,'28-38码 / 弹力面料 / 直筒修身 / 深蓝浅蓝',6800,1,'带弹力的牛仔裤，蹲下骑车都不勒。版型偏直筒，腿粗腿细穿都顺。三百块的日常通勤裤，买两条换着穿不心疼。','2026-09-26 23:30:33','2026-09-27 00:15:37');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2145,'优衣库 AIRism 速干T恤 男装圆领短袖 透气凉感夏季打底',9900,900,'/images/ai/zg_tshirt.jpg',4,9,'S-3XL / 凉感速干 / 圆领 / 黑白灰多色',21000,1,'夏天出汗不粘背那种，摸上去是凉的。当打底衫穿在衬衫里面也不显痕迹。百元内多买几件换洗，学生党宿舍常备。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2146,'优衣库女装 针织开衫 长袖薄款空调衫 秋冬百搭小外套',24900,340,'/images/ai/zg_fleece.jpg',4,9,'S-XL / 柔软针织 / 单排扣 / 多色',5200,1,'办公室空调冷的时候披一件刚好，不会热也不会冷。轻薄能塞包里，通勤族随手带着。搭裙子搭裤子都行，两百多的百搭款。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2147,'Nike耐克 Pegasus 41 男子缓震跑步鞋 透气飞线鞋面慢跑鞋',89900,150,'/images/ai/zg_sneaker.jpg',4,10,'39-45码 / ReactX泡棉 / 前后Zoom Air / 飞线鞋面',4300,1,'跑步圈公认的入门首选，日常慢跑十公里脚不累。ReactX中底比上一代回弹更好，膝盖压力小。预算九百想买双能跑能穿的选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2148,'Nike耐克 Air Force 1 07款 经典小白鞋 男女同款休闲板鞋',79900,220,'/images/ai/zg_boardshoe.jpg',4,10,'35.5-45码 / 全皮鞋面 / Air气垫 / 白色',79000,1,'永不过时的小白鞋，牛仔裤运动裤裙子都能配。皮面脏了湿巾一擦就干净。送男生送女生的经典款，不知道买什么鞋选它不会错。','2026-09-26 23:30:33','2026-09-27 00:18:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2149,'Nike耐克 Dunk Low 复古低帮板鞋 熊猫配色男女同款休闲鞋',79900,180,'/images/ai/zg_boardshoe.jpg',4,10,'35.5-45码 / 低帮 / 皮革拼接 / 黑白熊猫',15600,1,'熊猫配色是这几年最百搭的一双，穿校服穿工装都能压得住。鞋型显脚小，女生穿也好看。想入一双复古板鞋的选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2150,'Nike耐克 男子连帽卫衣 加绒保暖运动休闲上衣 秋冬款',49900,260,'/images/ai/zg_fleece.jpg',4,10,'S-2XL / 抓绒内里 / 连帽抽绳 / 多色',7200,1,'内里带绒，冬天单穿一件就够，不用套外套。版型宽松，健身房练完直接穿去上课都行。五百以内的品牌卫衣，学生党咬牙也值。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2151,'Nike耐克 Pro 女子高腰紧身裤 健身瑜伽运动长裤',39900,240,'/images/ai/zg_pants.jpg',4,10,'XS-XL / 高腰收腹 / 弹力速干 / 黑色',8100,1,'高腰款深蹲不下滑，练腿不用一直提裤子。面料速干不闷汗，跑步跳操都能穿。健身入门第一条紧身裤推荐它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2152,'adidas阿迪达斯 三叶草 Samba OG 复古德训鞋 男女同款板鞋',79900,160,'/images/ai/zg_boardshoe.jpg',4,79,'36-45码 / 麂皮拼接 / 生胶大底 / 黑白',16700,1,'这两年最火的德训鞋，复古又不挑衣服。生胶底薄贴地，走路稳。搭阔腿裤直筒裤都好看，想买双有个性的休闲鞋选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2153,'adidas阿迪达斯 Ultraboost Light 男子跑步鞋 缓震回弹跑鞋',129900,90,'/images/ai/zg_sneaker.jpg',4,79,'39-45码 / Light BOOST中底 / Primeknit鞋面',3200,1,'BOOST中底踩上去软弹，长距离跑后半程腿不容易僵。鞋面像袜子一样包脚，不磨脚背。预算一千三、跑量大的进阶跑者选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2154,'adidas阿迪达斯 男子三条杠运动裤 宽松直筒休闲长裤',34900,300,'/images/ai/zg_pants.jpg',4,79,'S-2XL / 侧边三条杠 / 抽绳松紧腰 / 黑色',9400,1,'经典三条杠，上课打球逛街都能穿。松紧腰不勒肚子，坐一天也舒服。三百多的运动裤，学生党开学季买一条穿一整年。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2155,'New Balance新百伦 574 经典复古慢跑鞋 男女同款休闲鞋',69900,200,'/images/ai/zg_boardshoe.jpg',4,80,'36-45码 / ENCAP中底 / 麂皮网面 / 灰蓝',11200,1,'NB最经典的入门款，灰色那双几乎人人有一双。鞋底软走路不累，站一天也不酸。七百内买双耐穿的复古跑鞋，通勤上学都合适。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2156,'New Balance新百伦 990v6 美产复古跑鞋 元祖灰男女同款',179900,55,'/images/ai/zg_boardshoe.jpg',4,80,'39-45码 / 美产 / FuelCell中底 / 元祖灰',2100,1,'NB的旗舰，美产做工和用料跟五百档完全两个级别。元祖灰是永远不会错的配色。预算一千八、想买双能穿五年的鞋就选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2157,'李宁 音速12 男子篮球鞋 碳板支撑实战外场耐磨球鞋',49900,180,'/images/ai/zg_sneaker.jpg',4,78,'39-46码 / 全掌碳板 / 橡胶外底耐磨 / 高帮',5600,1,'外场水泥地也能扛，耐磨底打一个学期不磨平。碳板支撑急停变向不崴脚。学生党打球的实战鞋，五百这个价位很难找到更好的。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2158,'李宁 超轻22 男子跑步鞋 轻量透气缓震 日常慢跑鞋',49900,230,'/images/ai/zg_sneaker.jpg',4,78,'39-45码 / 单只约230g / 䨻科技中底 / 网面透气',7800,1,'轻到上脚几乎没感觉，夏天跑五公里不闷脚。䨻中底回弹够但不会软到卸力。五百内想买双轻跑鞋的学生党选它。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2159,'李宁 中国李宁 男子圆领卫衣 国潮印花宽松休闲上衣',39900,210,'/images/ai/zg_fleece.jpg',4,78,'S-3XL / 纯棉毛圈 / 胸前印花 / 宽松版型',6300,1,'国潮那件，印花不土，配工装裤直接出门。纯棉毛圈不扎皮肤，秋天单穿冬天当内搭。四百块买国产设计感卫衣很划算。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2160,'安踏 氢跑鞋5.0 男子轻量跑步鞋 软弹缓震学生运动鞋',32900,320,'/images/ai/zg_sneaker.jpg',4,77,'39-45码 / 单只约200g / 氮科技中底 / 透气网面',9800,1,'三百出头的轻量跑鞋，体测跑一千米、操场刷圈都够用。氮科技中底软弹，脚感不输贵的。学生党第一双跑鞋闭眼买。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2161,'安踏 男子加绒运动裤 冬季保暖束脚休闲长裤 防风跑步',19900,400,'/images/ai/zg_pants.jpg',4,77,'S-3XL / 内里加绒 / 束脚口 / 侧口袋拉链',11300,1,'内里带绒，冬天骑车通勤腿不冻透。束脚口不漏风，跑步不缠鞋带。两百块的保暖运动裤，学生党过冬刚需。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2162,'波司登 男子极寒长款羽绒服 加厚鹅绒防风保暖冬季外套',129900,110,'/images/ai/zg_down_jacket.jpg',4,81,'S-3XL / 90%白鹅绒 / 极寒-30℃ / 长款过膝',4200,1,'北方零下二十度穿它出门不哆嗦，长款盖到大腿根。鹅绒比鸭绒轻且没味道，不压身。一千三买国产羽绒服旗舰款，比大牌划算太多。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2163,'波司登 女子轻薄羽绒服 短款修身白鸭绒保暖外套秋冬',59900,190,'/images/ai/zg_down_jacket.jpg',4,81,'S-XL / 90%白鸭绒 / 短款修身 / 多色',6700,1,'薄款不臃肿，里面穿毛衣外面套大衣都行。收纳后一小团塞包里，南方冬天出差带着正好。六百块的女款轻薄羽绒，送妈妈送女朋友都合适。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2164,'骆驼 三合一冲锋衣 男女同款户外防风防水抓绒内胆两件套',49900,220,'/images/ai/zg_down_jacket.jpg',4,82,'S-3XL / 外壳防水 / 抓绒内胆可拆 / 多色',8900,1,'外壳防风防水，内胆抓绒可拆，一件顶三季穿。爬山徒步遇到下雨不慌。五百块的入门冲锋衣，学生党第一次户外、日常骑车挡风都够用。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2165,'骆驼 户外徒步鞋 男女防滑登山鞋 透气耐磨爬山运动鞋',39900,260,'/images/ai/zg_sneaker.jpg',4,82,'35-45码 / 橡胶防滑大底 / 鞋头防撞 / 透气网面',7400,1,'大底齿深，湿石头上踩得住不打滑。鞋头有防撞包头，踢到石头脚趾不疼。四百块入门徒步鞋，周末爬山、走长线旅游都合适。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2166,'京造 20寸登机箱 铝合金框拉杆箱 静音万向轮旅行箱免托运',29900,180,'/images/ai/zg_luggage.jpg',4,14,'20寸 / PC箱体 / 静音万向轮 / TSA海关锁',5100,1,'20寸能直接带上飞机不用托运，短途出差两三天够装。轮子安静，宿舍走廊拉着不吵人。三百块的行李箱，学生党回家、实习租房都用得上。','2026-09-26 23:30:33','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2167,'三只松鼠 坚果大礼包1.4kg 混合干果零食礼盒 节日送长辈',12900,600,'/images/ai/zg_nuts.jpg',5,11,'1.4kg / 9袋混合 / 独立包装 / 礼盒装',23400,1,'一整箱九袋不同口味，过年过节送长辈送同事都体面。独立小包不怕受潮，办公室抽屉放一箱随时吃。一百多块的礼盒装是送礼最省心的选择。','2026-09-26 23:32:54','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2168,'三只松鼠 手撕面包1kg 整箱早餐糕点 学生党宿舍代餐零食',2990,1200,'/images/ai/zg_bread.jpg',5,11,'1kg / 约20包 / 奶香味 / 独立包装',31200,1,'早上来不及去食堂，书包塞两个就能顶到中午。三十块一整箱，学生党月底救急的口粮。宿舍囤一箱当早餐当夜宵都行。','2026-09-26 23:32:54','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2169,'三只松鼠 芒果干108g*3袋 果干蜜饯零食 酸甜解腻',1990,900,'/images/ai/zg_fruit.jpg',5,11,'108g*3 / 泰国风味 / 无添加色素',12800,1,'追剧的时候吃这个比薯片健康，酸甜不齁。二十块三包，办公室下午茶、上课偷吃都合适。想吃甜又怕长痘的可以拿它替代奶茶。','2026-09-26 23:32:54','2026-09-27 00:15:38');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2170,'良品铺子 猪肉脯200g 靖江特产肉干零食 高蛋白解馋',2590,700,'/images/ai/zg_snack_gift.jpg',5,70,'200g / 猪肉含量90% / 蜜汁原味',18600,1,'肉厚有嚼劲，比辣条顶饿，健身嘴馋的时候来两片比薯片强。二十六块一袋，办公室抽屉常备。送男生零食首选，比甜的更受欢迎。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2171,'良品铺子 零食大礼包 混合装整箱 追剧解馋休闲食品',5990,500,'/images/ai/zg_snack_gift.jpg',5,70,'约1.2kg / 20种混合 / 甜辣都有',14300,1,'二十种口味一次尝遍，甜的辣的都有，宿舍四个人分着吃刚好。六十块的量当追剧零食能吃两周。不知道买什么零食的时候选大礼包最不踩雷。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2172,'百草味 碧根果218g 奶油味坚果炒货 每日坚果零食',2390,800,'/images/ai/zg_nuts.jpg',5,71,'218g / 奶油味 / 开口好剥',9700,1,'开口大好剥，不用夹子也能捏开。奶油味不齁，看剧一把一把停不下来。二十四块一袋，考研复习桌上放一袋补脑解闷。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2173,'百草味 夏威夷果268g 奶油味大颗坚果 高端炒货零食',2990,650,'/images/ai/zg_nuts.jpg',5,71,'268g / 大颗粒 / 附赠开口器',8400,1,'颗粒大奶香浓，配开口器一转就开。三十块一袋当轻奢零食，送人比瓜子体面。办公室下午饿了来两颗，比饼干扛饿还不长胖。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2174,'洽洽 香瓜子260g*5袋 焦糖山核桃味炒货 追剧休闲零食',2490,1000,'/images/ai/zg_nuts.jpg',5,72,'260g*5 / 焦糖味 / 独立袋装',26800,1,'洽洽瓜子是国民款，颗粒饱满不空壳。五袋装二十五块，宿舍聚餐、过年待客摆一盘最实在。焦糖味比原味更上瘾，追剧必备。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2175,'洽洽 小黄袋每日坚果750g 30包混合坚果果干 孕妇学生',5990,750,'/images/ai/zg_nuts.jpg',5,72,'750g / 30小包 / 4种坚果+3种果干',34500,1,'一天一小包不用自己配，坚果果干都齐了。六十块吃一个月，比天天买奶茶划算太多。上班族带饭加一包、学生党课间补能量的常规操作。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2176,'伊利 金典纯牛奶250ml*12盒 3.6g乳蛋白 整箱早餐奶',5990,900,'/images/ai/zg_milk.jpg',5,73,'250ml*12 / 3.6g蛋白 / 全脂纯牛奶',128000,1,'蛋白比普通奶高一档，早上配面包一盒顶到中午。六十块一箱十二盒，全家喝一周。给老人小孩囤奶、学生党宿舍早餐都选它。','2026-09-26 23:32:54','2026-09-27 00:18:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2177,'伊利 安慕希希腊风味酸奶205g*12盒 常温酸奶整箱',4990,800,'/images/ai/zg_yogurt.jpg',5,73,'205g*12 / 浓郁希腊风味 / 常温保存',38900,1,'常温酸奶不用冷藏，宿舍没冰箱也能囤。浓稠能挂勺，加麦片当早餐很顶饱。五十块一箱，减脂期嘴馋想喝甜的就用它替代奶茶。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2178,'蒙牛 特仑苏纯牛奶250ml*12盒 3.6g优质乳蛋白 高端奶',6490,850,'/images/ai/zg_milk.jpg',5,74,'250ml*12 / 3.6g蛋白 / 专属牧场',36700,1,'特仑苏是国产高端奶的老牌，奶味浓不腥。六十五块一箱，走亲戚探望病人提着体面。家里老人小孩每天一盒，补钙最省事的办法。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2179,'认养一头牛 全脂纯牛奶250ml*10盒 生牛乳整箱早餐奶',4990,600,'/images/ai/zg_milk.jpg',5,92,'250ml*10 / 全脂 / 自有牧场奶源',15200,1,'自有牧场直供，奶味偏甜不寡淡。五十块十盒比大牌便宜一档，日常当水喝不心疼。学生党宿舍早餐、上班族通勤带一盒都合适。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2180,'海天 金标生抽1.9L 家用酿造酱油 炒菜凉拌提鲜',1990,700,'/images/ai/zg_oil_rice.jpg',5,75,'1.9L / 酿造酱油 / 特级',19800,1,'二十块能买将近四斤，租房自己做饭一瓶用半年。炒菜凉拌都靠它提鲜，新手厨房第一瓶酱油。大瓶装比小瓶划算太多。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2181,'海天 上等蚝油700g*2瓶 家用炒菜提鲜调味料 挤压装',2290,600,'/images/ai/zg_oil_rice.jpg',5,75,'700g*2 / 挤压瓶 / 蚝汁含量高',16400,1,'炒青菜放一勺就有味，厨房小白也能炒出饭店感。挤压瓶不脏手，两瓶装二十三块。刚开始自己做饭、租房开火的第一套调味料。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2182,'金龙鱼 食用调和油5L 家用炒菜植物油 非转基因',5990,500,'/images/ai/zg_oil_rice.jpg',5,76,'5L / 1:1:1调和 / 非转基因',21300,1,'六十块五升，家里做饭两个月不用操心油。调和油配比均衡，煎炒炸都合适。囤货装比小瓶划算，租房自己开火的家庭必备。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2183,'金龙鱼 东北大米10kg 珍珠米圆粒 家用口粮米真空装',6990,450,'/images/ai/zg_oil_rice.jpg',5,76,'10kg / 东北珍珠米 / 真空包装',18700,1,'东北圆粒米，煮出来油亮有嚼头，冷饭也不硬。七十块二十斤，一家人吃一个多月。真空装不生虫，租房囤粮、给爸妈寄都合适。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2184,'三顿半 精品速溶咖啡24颗混合装 冷萃超即溶咖啡粉',12900,300,'/images/ai/zg_coffee.jpg',5,91,'24颗 / 6种烘焙度 / 冷水3秒溶解',22400,1,'冷水三秒就化开，宿舍没热水没咖啡机也能喝。一百多块二十四杯，比天天买星巴克省一半还多。考研党熬夜、上班族提神靠它续命。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2185,'褚橙 云冠橙冰糖心甜橙5斤 云南当季新鲜水果整箱',7900,400,'/images/ai/zg_fruit.jpg',5,93,'5斤 / 单果约180g / 冰糖心 / 当季现摘',11600,1,'皮薄汁多，切开能看到糖心，酸甜比例刚好不齁。八十块五斤，比水果店便宜不少。给宿舍同学分、给爸妈寄一箱，当季补维C最实在。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2186,'獐子岛 冷冻扇贝肉500g 海鲜生鲜去壳贝柱 家用食材',4990,350,'/images/ai/zg_snack_gift.jpg',5,94,'500g / 去壳扇贝肉 / 冷链急冻',6300,1,'已经去壳处理好了，蒜蓉粉丝一蒸十分钟上桌，新手也能做硬菜。五十块一斤，比买活扇贝省事还不脏手。租房想加个菜、给家里做年夜饭都用得上。','2026-09-26 23:32:54','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2187,'迪卡侬 男子速干运动短裤 跑步健身五分裤 透气轻薄夏季',7990,600,'/images/ai/zg_tshirt.jpg',6,13,'S-2XL / 速干面料 / 内衬防走光 / 多色',16000,1,'八十块的速干短裤，跑五公里不粘腿，洗完一晚上就干。带内衬不用再穿一条。学生党体育课、健身房日常穿都够用，一次买三条换着穿。','2026-09-26 23:34:11','2026-09-27 00:18:41');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2188,'迪卡侬 瑜伽垫8mm加厚 防滑家用健身垫 女生初学者运动垫',9900,500,'/images/ai/zg_yogamat.jpg',6,13,'183*61cm / 8mm加厚 / 双面防滑 / 附绑带',22000,1,'八毫米厚度，做卷腹下犬式膝盖不硌地。双面防滑，出汗也不打滑。宿舍铺地上练帕梅拉、家里做拉伸都行，一百块内最稳的入门垫。','2026-09-26 23:34:11','2026-09-27 00:18:41');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2189,'迪卡侬 可调节哑铃20kg 家用力量训练健身器材 男士增肌',29900,180,'/images/ai/zg_dumbbell.jpg',6,13,'2只共20kg / 重量可拆调 / 包胶防砸地板',5200,1,'在家练不用办健身卡，一对哑铃能练遍全身。包胶的不砸坏地板，租房也放心。三百块入手，比一年年卡便宜太多，想增肌的男生宿舍家里都合适。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2190,'迪卡侬 羽毛球拍双拍套装 碳素一体超轻 初学者家庭娱乐',12900,320,'/images/ai/zg_badminton.jpg',6,13,'2支装 / 碳素一体 / 约85g / 附拍套',9600,1,'两支装一百三，跟同学室友去球馆直接开打。碳素一体比铁合金轻，挥一下午手不酸。新手入门、公司团建、周末和家人玩都合适。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2191,'迪卡侬 无绳跳绳 负重手柄家用健身 静音室内燃脂运动',3990,700,'/images/ai/zg_jumprope.jpg',6,13,'无绳设计 / 负重手柄 / 计数功能',11200,1,'无绳的那种，在宿舍客厅跳都不会打到家具，也不吵楼下。四十块的燃脂神器，跳十分钟出一身汗。下雨天出不去又想运动的选它。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2192,'Keep 智能动感单车C1 家用静音健身车 磁控阻力直播课',199900,60,'/images/ai/zg_spinbike.jpg',6,85,'磁控静音 / 32档阻力 / 直播课程 / 承重120kg',1800,1,'磁控阻力几乎没有声音，晚上骑车不吵家人。跟着直播课踩有教练带节奏，比自己瞎练坚持得久。两千块买台家用健身车，比健身卡长期算更划算。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2193,'Keep 天然橡胶瑜伽垫 加宽防滑专业健身垫 男女通用',19900,240,'/images/ai/zg_yogamat.jpg',6,85,'185*68cm / 天然橡胶 / 4.5mm / 加宽',7400,1,'天然橡胶抓地力强，木地板上做下犬式不往前滑。加宽五厘米，男生翻身也不会出界。两百块的专业垫，练得比较认真的选它比入门款舒服很多。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2194,'Keep 智能运动手环B3 心率血氧睡眠监测 防水长续航',19900,400,'/images/ai/zg_band.jpg',6,85,'1.47英寸AMOLED / 心率血氧 / 50米防水 / 14天续航',8900,1,'两百块的手环，心率血氧睡眠都能测，跑步能看配速。充一次用两周，洗澡游泳都不用摘。刚开始健身想有点数据反馈的选它，比手表便宜太多。','2026-09-26 23:34:11','2026-09-27 00:15:39');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2195,'挪客 户外露营帐篷3-4人 双层防雨防紫外线 家庭野餐装备',39900,150,'/images/ai/zg_tent.jpg',6,83,'3-4人 / 双层防雨PU3000 / 银胶防晒 / 约3.5kg',4600,1,'四百块的三四人帐篷，周末带家人去公园野餐、新手第一次露营都够用。双层防雨，下小雨也不渗。三点五公斤一个人能背，不用开车也能去。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2196,'挪客 户外天幕 遮阳防紫外线银胶涂层 露营野餐凉棚',29900,180,'/images/ai/zg_tent.jpg',6,83,'3*3m / 银胶涂层UPF50+ / 附风绳地钉',3100,1,'夏天露营没天幕等于暴晒，撑起来一片阴凉能坐一下午。银胶涂层防晒到位，午后也不闷。三百块的入门天幕，跟帐篷配一套就很像样。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2197,'牧高笛 户外睡袋 加厚保暖露营旅行 可拼接成人款',19900,220,'/images/ai/zg_sleepbag.jpg',6,84,'适用15℃左右 / 可拼接 / 压缩收纳约2kg',5300,1,'两百块的睡袋，春秋露营、火车硬卧、学生宿舍午休都能用。两个能拼成双人，情侣露营更方便。压缩后一小团，塞背包不占地方。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2198,'牧高笛 折叠桌椅套装 户外露营便携铝合金 一桌四椅',29900,160,'/images/ai/zg_campchair.jpg',6,84,'1桌4椅 / 铝合金 / 折叠收纳 / 承重50kg',4200,1,'一桌四椅三百块，露营野餐直接坐下来吃饭不用蹲着。铝合金轻，折叠后能塞后备箱一角。周末带娃去公园、跟朋友户外聚会都用得上。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2199,'尤尼克斯 天斧88D PRO 羽毛球拍 进攻型单拍碳素',129900,70,'/images/ai/zg_badminton.jpg',6,86,'4U约83g / 全碳素 / 进攻型 / 已穿线',2400,1,'进攻型神拍，杀球下沉又快又重，打双打后场特别爽。一千多的价位是业余进阶的分水岭。打了两年球想升级装备、或者送给球友的选它。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2200,'尤尼克斯 羽毛球AS-03 耐打训练球 12只装鹅毛球',8900,400,'/images/ai/zg_badminton.jpg',6,86,'12只/筒 / 鹅毛 / 中速76号',9800,1,'耐打款，一颗能打两三局不散架，比杂牌球省。九十块一筒，俱乐部约球自带球的常规消耗。经常打球的学生党囤两筒最合适。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2201,'红双喜 乒乓球拍 双面反胶成品拍 初学者家用娱乐拍',12900,280,'/images/ai/zg_badminton.jpg',6,87,'双面反胶 / 五层底板 / 附球2只',8600,1,'国产老牌成品拍，一百多块手感就不错，公司活动室、家里球台都能打。附赠球，拆开即用。新手入门、送长辈陪着锻炼的稳妥选择。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2202,'斯伯丁 NBA比赛用篮球7号 室内外通用耐磨PU篮球',29900,200,'/images/ai/zg_basketball.jpg',6,88,'7号标准 / PU材质 / 室内外通用',6700,1,'手感比几十块的橡胶球好一个档次，投球不打滑。PU材质水泥地也能打，耐磨不掉皮。三百块的学生党主力球，班级比赛、日常约球都用它。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2203,'佳明 Forerunner 265 跑步GPS运动手表 AMOLED屏心率',329900,55,'/images/ai/zg_smartwatch.jpg',6,89,'1.3英寸AMOLED / 多频GPS / 心率血氧 / 13天续航',3200,1,'跑步党最认的一块表，GPS轨迹准得能画出操场第几道。续航十三天，跑马拉松完全不用担心中途没电。三千多的进阶装备，认真训练的选它不后悔。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2204,'佳明 Instinct 3 本能太阳能户外运动手表 三防军规',399900,40,'/images/ai/zg_smartwatch.jpg',6,89,'太阳能充电 / 军规三防 / 多频GPS / 无限续航',1600,1,'太阳能充电款，户外光照足基本不用插线。军规三防，磕碰泡水沙尘都不怕。四千档的硬核户外表，徒步登山、经常出差野外的选它最省心。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2205,'小米手环9 标准版 运动健康智能手环 心率睡眠监测防水',19900,800,'/images/ai/zg_band.jpg',6,1,'1.62英寸AMOLED / 心率血氧 / 5ATM防水 / 21天续航',143000,1,'两百块以内最能打的手环，续航二十一天，一个月充一次。跑步游泳都能戴，还能刷门禁。学生党第一块智能设备、想开始记录运动的选它。','2026-09-26 23:34:11','2026-09-27 00:15:40');
INSERT INTO `tb_item` (`id`, `name`, `price`, `stock`, `image`, `category_id`, `brand_id`, `spec`, `sales`, `status`, `description`, `create_time`, `update_time`) VALUES (2206,'骆驼 折叠登山杖 超轻铝合金伸缩手杖 户外爬山徒步装备',9900,300,'/images/ai/zg_trekpole.jpg',6,82,'折叠约35cm / 铝合金 / 承重100kg / 单支',4800,1,'折叠后只有三十五厘米，塞背包侧袋就走。下山时撑着能省膝盖一大半压力，爬长线特别明显。一百块的登山杖，第一次爬武功山、黄山都该带。','2026-09-26 23:34:11','2026-09-27 00:15:40');
